use super::*;
use query::{VolumeQuery, do_query};
use search_cancel::CancellationToken;
use std::{os::unix::fs::MetadataExt, process::Command};

// Generated by r6's SearchCache::from_volume_tree: a one-TiB prior.raw and
// an 8-KiB other.bin. Its v6 snapshot contains only logical lengths.
fn legacy_volume_fixture() -> Vec<u8> {
    use base64::{Engine, engine::general_purpose::STANDARD};
    STANDARD
        .decode(concat!(
            "KLUv/QRYHAYAksonLKApHf//D//vKhZ+WiNky0RlkoKS/S38vMiQIew6247W9kL8CzzujheCt5QpqlSk",
            "OfNmh8pSqhJmeS6k6uMH5hvFVhazPFJaqEaaM292qChVJZdaAXPOKaCJ6r/mZ8hC8a2bIHoB4d3GBgpv",
            "3tBt4zf65o0BxzlwGMRIgqXY0KHg8fEtZD+CNQSM9SlOMEMCJLXHD28Kza+bpHY0TAVADABPN6wFT041D",
            "M67cMSJOvWCERZgqhTuzSmmJsXQ3555AQAAX3NOhA==",
        ))
        .unwrap()
}

#[test]
fn old_volume_keeps_names_and_logical_sizes_offline_until_its_disk_returns() {
    let db = std::env::temp_dir().join(format!("cardinal-{}.db", mounts::separate_snapshot_id()));
    let old = legacy_volume_fixture();
    fs::write(&db, &old).unwrap();
    let header = read_snapshot_header(&db).unwrap();
    assert_eq!(header.source_version, 6);
    assert_eq!(header.last_event_id, 123);
    // Even a valid, continuous event cursor cannot supply historical allocations.
    assert!(journal_resume(&db, &header.path, header.last_event_id).is_none());
    let source = Volume::new("test-offline", header.path, "apfs", Some(db.clone()));
    for direction in [
        search_cache::SortDirection::Asc,
        search_cache::SortDirection::Desc,
    ] {
        let files = rows(
            &source,
            "prior.raw",
            Some(SortStatePayload {
                key: search_cache::SortKey::Size,
                direction,
            }),
        );
        assert_eq!(files.len(), 1);
        assert_eq!(files[0]["metadata"]["size"], 1u64 << 40);
        assert_eq!(
            files[0]["metadata"].get("allocatedSize"),
            Some(&serde_json::Value::Null)
        );
    }
    assert_eq!(fs::read(&db).unwrap(), old);
    fs::remove_file(db).unwrap();
}

fn fixture_mounts(label: &str) -> Vec<Mount> {
    discover()
        .unwrap()
        .into_iter()
        .filter(|m| {
            m.path
                .file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with(label)
        })
        .collect()
}

fn rows(source: &Volume, query: &str, sort: Option<SortStatePayload>) -> Vec<serde_json::Value> {
    scoped_rows(source, query, sort, &[])
}

fn scoped_rows(
    source: &Volume,
    query: &str,
    sort: Option<SortStatePayload>,
    excluded: &[&str],
) -> Vec<serde_json::Value> {
    let request = VolumeQuery {
        query: Some(query.into()),
        directory_query: None,
        case_sensitive: false,
        sort,
        offset: 0,
        limit: 256,
        request_id: 1,
        excluded_paths: excluded.iter().map(PathBuf::from).collect(),
    };
    let reply = do_query(source, request, CancellationToken::noop()).unwrap();
    serde_json::to_value(reply).unwrap()["rows"]
        .as_array()
        .unwrap()
        .clone()
}
use crate::sort::SortStatePayload;
#[track_caller]
fn wait(mut check: impl FnMut() -> bool) {
    let deadline = Instant::now() + Duration::from_secs(25);
    while !check() {
        assert!(
            Instant::now() < deadline,
            "Timed out waiting for volume state"
        );
        thread::sleep(Duration::from_millis(75));
    }
}
fn hdi(args: &[&OsStr]) {
    let out = Command::new("/usr/bin/hdiutil")
        .args(args)
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "hdiutil: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}
struct Image {
    file: PathBuf,
    path: Option<PathBuf>,
}
impl Image {
    fn new(dir: &Path, file: &str, fs_type: &str, label: &str) -> Self {
        let file = dir.join(file);
        hdi(&[
            "create".as_ref(),
            "-size".as_ref(),
            "96m".as_ref(),
            "-fs".as_ref(),
            fs_type.as_ref(),
            "-volname".as_ref(),
            label.as_ref(),
            file.as_os_str(),
        ]);
        Self { file, path: None }
    }
    fn attach(&mut self, path: &Path) {
        assert!(!path.exists());
        hdi(&[
            "attach".as_ref(),
            "-nobrowse".as_ref(),
            "-mountpoint".as_ref(),
            path.as_os_str(),
            self.file.as_os_str(),
        ]);
        self.path = Some(path.into());
    }
    fn detach(&mut self) {
        if let Some(path) = self.path.take() {
            hdi(&["detach".as_ref(), path.as_os_str()]);
        }
    }
}
impl Drop for Image {
    fn drop(&mut self) {
        self.detach();
    }
}

#[test]
#[ignore = "mounts two isolated macOS disk images"]
fn mounted_disk_images_search_updates_and_offline_restart() {
    let _ = tracing_subscriber::fmt()
        .with_env_filter("cardinal_lib::volumes=trace")
        .try_init();
    let parent =
        PathBuf::from(std::env::var_os("CARDINAL_VOLUME_TEST_DIR").expect("isolated QA directory"));
    let label = format!("CardinalR5Test{}", std::process::id());
    let work = parent.join(&label);
    fs::create_dir_all(&work).unwrap();
    let cache_dir = work.join("volumes");
    let mount = Path::new("/Volumes").join(&label);
    let renamed = PathBuf::from(format!("{}-renamed", mount.display()));
    let mut a = Image::new(&work, "first.dmg", "JHFS+", &label);
    let mut b = Image::new(&work, "second.dmg", "APFS", &label);
    a.attach(&mount);
    let small = mount.join("needle-small.txt");
    let large = mount.join("needle-large.txt");
    fs::write(&small, b"12").unwrap();
    fs::write(small.join("..namedfork/rsrc"), [1u8; 16_384]).unwrap();
    fs::write(&large, [1u8; 8_192]).unwrap();
    let blocks = |p: &Path| fs::symlink_metadata(p).unwrap().blocks() * 512;
    let small_allocated = blocks(&small);
    let large_allocated = blocks(&large);
    assert!(small_allocated > large_allocated);
    let hot_file = mount.join("hot-metadata.tmp");
    fs::write(&hot_file, [0]).unwrap();
    let dir = mount.join("Nested");
    fs::create_dir(&dir).unwrap();
    fs::write(dir.join("needle-delete.txt"), b"12345").unwrap();
    let store = Volumes::default();
    store.restore(&cache_dir).unwrap();
    let notify: Notify = Arc::new(|| {});
    let mounted = fixture_mounts(&label);
    assert_eq!(
        mounted.len(),
        1,
        "Disk Arbitration should discover the mounted test image"
    );
    let first = mounted[0].clone();
    assert!(first.persistent);
    let workers = store.reconcile(&cache_dir, mounted, &notify);
    let src = store.get(&first.id).unwrap();
    wait(|| !src.meta.lock().info.indexing);
    let sort = |direction| {
        Some(SortStatePayload {
            key: search_cache::SortKey::Size,
            direction,
        })
    };
    let asc = rows(&src, "needle", sort(search_cache::SortDirection::Asc));
    let desc = rows(&src, "needle", sort(search_cache::SortDirection::Desc));
    assert_eq!(asc.last(), desc.first());
    assert_eq!(desc[0]["metadata"]["size"], 2);
    assert_eq!(desc[0]["metadata"]["allocatedSize"], small_allocated);
    assert_eq!(desc[1]["metadata"]["allocatedSize"], large_allocated);
    fs::rename(
        mount.join("needle-small.txt"),
        dir.join("needle-renamed.txt"),
    )
    .unwrap();
    fs::write(dir.join("needle-live.txt"), b"live added").unwrap();
    fs::remove_file(dir.join("needle-delete.txt")).unwrap();
    wait(|| {
        rows(&src, "needle-live", None).len() == 1
            && rows(&src, "needle-delete", None).is_empty()
            && rows(&src, "needle-renamed", None).len() == 1
    });
    for size in [17, 159, 997] {
        fs::write(&hot_file, vec![0; size]).unwrap();
    }
    wait(|| rows(&src, "hot-metadata", None)[0]["metadata"]["size"] == 997);
    let hot_allocated = blocks(&hot_file);
    let t = Instant::now();
    a.detach();
    store.reconcile(&cache_dir, fixture_mounts(&label), &notify);
    for w in workers {
        w.join().unwrap();
    }
    assert!(!src.meta.lock().info.online);
    assert_eq!(rows(&src, "needle", None).len(), 3);
    assert_eq!(scoped_rows(&src, "needle", None, &["Nested"]).len(), 1);
    eprintln!("eject and final checkpoint: {:?}", t.elapsed());

    let store = Volumes::default();
    store.restore(&cache_dir).unwrap();
    let src = store.get(&first.id).unwrap();
    let hot = rows(&src, "hot-metadata", None);
    assert_eq!(hot[0]["metadata"]["size"], 997);
    assert_eq!(hot[0]["metadata"]["allocatedSize"], hot_allocated);
    let t = Instant::now();
    let saved = rows(&src, "needle", sort(search_cache::SortDirection::Desc));
    assert_eq!(saved.len(), 3);
    assert_eq!(saved[0]["metadata"]["size"], 2);
    assert_eq!(saved[0]["metadata"]["allocatedSize"], small_allocated);
    assert!(saved[0]["metadata"]["mtime"].as_u64().unwrap() > 0);
    eprintln!("offline restore/search/size-sort: {:?}", t.elapsed());

    b.attach(&mount);
    fs::write(mount.join("different-disk.txt"), b"second").unwrap();
    let sparse = mount.join("prior.raw");
    fs::write(&sparse, b"head").unwrap();
    fs::OpenOptions::new()
        .write(true)
        .open(&sparse)
        .unwrap()
        .set_len(1 << 40)
        .unwrap();
    let sparse_allocated = blocks(&sparse);
    let dense = mount.join("other.bin");
    fs::write(&dense, [1u8; 8192]).unwrap();
    let dense_allocated = blocks(&dense);
    assert!(dense_allocated > sparse_allocated);
    let mounted = fixture_mounts(&label);
    let second = mounted[0].clone();
    assert_ne!(second.id, first.id);
    assert!(!first.verified_path(&mount.join("needle-large.txt")));
    let prior_dir = cache_dir.join(&second.id);
    fs::create_dir(&prior_dir).unwrap();
    let prior_db = prior_dir.join(format!(
        "apfs.{}.db",
        second.journal.as_deref().unwrap_or("none")
    ));
    fs::write(&prior_db, legacy_volume_fixture()).unwrap();
    let store = Volumes::default();
    store.restore(&cache_dir).unwrap();
    let src = store.get(&first.id).unwrap();
    let src_b = store.get(&second.id).unwrap();
    assert!(!src_b.meta.lock().info.online);
    let old = rows(&src_b, "prior.raw", None);
    assert_eq!(old[0]["metadata"]["size"], 1u64 << 40);
    assert_eq!(
        old[0]["metadata"].get("allocatedSize"),
        Some(&serde_json::Value::Null)
    );
    let workers = store.reconcile(&cache_dir, mounted, &notify);
    wait(|| !src_b.meta.lock().info.indexing);
    let current_db = src_b.meta.lock().snapshot.clone().unwrap();
    assert_eq!(
        read_snapshot_header(&current_db).unwrap().source_version,
        search_cache::LSF_VERSION
    );
    assert_eq!(journal_resume(&current_db, &mount, 123), Some((123, false)));
    let actual = rows(&src_b, "prior.raw", None);
    assert_eq!(actual[0]["metadata"]["allocatedSize"], sparse_allocated);
    assert_eq!(
        rows(&src_b, "other.bin", None)[0]["metadata"]["allocatedSize"],
        dense_allocated
    );
    assert_eq!(rows(&src_b, "different-disk", None).len(), 1);
    assert!(rows(&src_b, "needle", None).is_empty());
    assert!(rows(&src, "different-disk", None).is_empty());
    assert!(!src.meta.lock().info.online);
    b.detach();
    store.reconcile(&cache_dir, fixture_mounts(&label), &notify);
    for w in workers {
        w.join().unwrap();
    }
    let reopened = Volumes::default();
    reopened.restore(&cache_dir).unwrap();
    let offline = reopened.get(&second.id).unwrap();
    assert!(!offline.meta.lock().info.online);
    let sorted = rows(
        &offline,
        "prior.raw|other.bin",
        sort(search_cache::SortDirection::Desc),
    );
    assert_eq!(sorted.len(), 2);
    assert_eq!(sorted[0]["metadata"]["allocatedSize"], dense_allocated);
    assert_eq!(sorted[1]["metadata"]["allocatedSize"], sparse_allocated);

    // Simulate changes while Cardinal was closed and a different mount point on return.
    a.attach(&renamed);
    fs::write(renamed.join("while-away.txt"), b"new").unwrap();
    let workers = store.reconcile(&cache_dir, fixture_mounts(&label), &notify);
    wait(|| !src.meta.lock().info.indexing && rows(&src, "while-away", None).len() == 1);
    assert_eq!(scoped_rows(&src, "needle", None, &["Nested"]).len(), 1);
    assert!(
        rows(&src, "needle", None)
            .iter()
            .all(|v| Path::new(v["path"].as_str().unwrap()).starts_with(&renamed))
    );
    assert_eq!(store.list().len(), 2);
    a.detach();
    store.reconcile(&cache_dir, fixture_mounts(&label), &notify);
    for w in workers {
        w.join().unwrap();
    }
    for img in [&a, &b] {
        fs::remove_file(&img.file).unwrap();
    }
}

#[test]
fn volume_exclusions_filter_the_whole_order_and_undo_without_disk_access() {
    use fswalk::Node;
    fn node(name: &str, children: Vec<Node>) -> Node {
        Node {
            name: name.into(),
            metadata: None,
            children,
        }
    }
    let tree = node(
        "Drive",
        vec![
            node("cache", vec![node("hit-a", vec![])]),
            node("cache-old", vec![node("hit-b", vec![])]),
            node("hit-c", vec![]),
            node("hit-d", vec![]),
        ],
    );
    let mut index = Index::new(SearchCache::from_volume_tree(
        Path::new("/Volumes/Absent"),
        &tree,
        vec![],
        1,
        &APP_QUIT,
    ));
    let page = |index: &mut Index, paths: &[&str], offset| {
        let request = VolumeQuery {
            query: Some("hit-".into()),
            directory_query: None,
            case_sensitive: true,
            sort: Some(SortStatePayload {
                key: search_cache::SortKey::Filename,
                direction: search_cache::SortDirection::Asc,
            }),
            offset,
            limit: 1,
            request_id: 1,
            excluded_paths: paths.iter().map(PathBuf::from).collect(),
        };
        index
            .page(request, CancellationToken::noop())
            .map(|p| serde_json::to_value(p).unwrap())
    };
    let excluded = ["cache", "cache/hit-a", "hit-c"];
    let first = page(&mut index, &excluded, 0).unwrap();
    assert_eq!(first["total"], 2);
    assert_eq!(first["rows"][0]["path"], "/Volumes/Absent/cache-old/hit-b");
    assert_eq!(
        page(&mut index, &excluded, 1).unwrap()["rows"][0]["path"],
        "/Volumes/Absent/hit-d"
    );
    assert_eq!(page(&mut index, &[], 0).unwrap()["total"], 4);
    assert!(page(&mut index, &["../other"], 0).is_err());
    assert!(page(&mut index, &["/Volumes"], 0).is_err());
}

#[test]
fn offline_large_volume_sorts_and_pages_every_match_without_accessing_the_mount() {
    use fswalk::{Node, NodeFileType, NodeMetadata};
    use search_cache::{SortDirection, SortKey};
    use std::num::NonZeroU64;
    let n = 30_000usize;
    let file = |i: usize| Node {
        name: format!("item-{i:05}").into(),
        metadata: Some(NodeMetadata {
            r#type: NodeFileType::File,
            size: ((i * 19) % n) as u64,
            allocated_size: (n - 1 - ((i * 19) % n)) as u64,
            ctime: NonZeroU64::new(1 + ((i * 7) % n) as u64),
            mtime: NonZeroU64::new(1 + ((i * 11) % n) as u64),
        }),
        children: vec![],
    };
    let tree = Node {
        name: "Fixture".into(),
        metadata: None,
        children: (0..n).map(file).collect(),
    };
    let mount = Path::new("/Volumes/Cardinal-unmounted-fixture");
    let mut index = Index::new(SearchCache::from_volume_tree(
        mount,
        &tree,
        vec![],
        1,
        &APP_QUIT,
    ));
    for (key, attr) in [
        (SortKey::Size, "allocatedSize"),
        (SortKey::Ctime, "ctime"),
        (SortKey::Mtime, "mtime"),
    ] {
        for direction in [SortDirection::Asc, SortDirection::Desc] {
            for offset in [0, 14_999, n - 7] {
                let request = VolumeQuery {
                    query: Some("item-".into()),
                    directory_query: None,
                    case_sensitive: false,
                    sort: Some(SortStatePayload { key, direction }),
                    offset,
                    limit: 256,
                    request_id: 1,
                    excluded_paths: vec![],
                };
                let json =
                    serde_json::to_value(index.page(request, CancellationToken::noop()).unwrap())
                        .unwrap();
                assert_eq!(json["total"], n);
                for (j, row) in json["rows"].as_array().unwrap().iter().enumerate() {
                    let rank = if direction == SortDirection::Asc {
                        offset + j
                    } else {
                        n - 1 - offset - j
                    };
                    assert_eq!(
                        row["metadata"][attr],
                        rank + usize::from(key != SortKey::Size)
                    );
                }
            }
        }
    }
}
